"""Finding the stretches of opening hours nobody covers."""

from typing import List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans
from hourglass.errors import ProjectError

Spans = List[Span]


def _check_inside(spans: Spans, opening: Span):
    for span in spans:
        if span.start < opening.start or (
            span.end > opening.end
        ):
            raise ProjectError(
                f"{format_span(span)} is outside opening"
            )


def _uncovered(spans: Spans, opening: Span) -> Spans:
    edges = [opening.start]
    for span in spans:
        edges += [span.start, span.end]
    edges.append(opening.end)
    pairs = zip(edges[::2], edges[1::2])
    return [Span(a, b) for a, b in pairs if a < b]


# ---
def find_gaps(worked: Spans, opening: Span) -> List[str]:
    """One label per gap, e.g. gap 12:00-13:00 (60 min)."""
    spans = merge_spans(worked)
    _check_inside(spans, opening)
    return [
        f"gap {format_span(g)} ({g.minutes} min)"
        for g in _uncovered(spans, opening)
    ]

